package pe.com.dentalamericana.booking;import jakarta.persistence.*;import java.time.*;@Entity@Table(name="solicitudes_cita_web")public class PublicBookingRequest{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="nombre_completo",nullable=false)private String fullName;@Column(name="numero_documento")private String documentNumber;@Column(nullable=false)private String celular;private String email;@Column(nullable=false)private String servicio;@Column(name="fecha_preferida")private LocalDate preferredDate;@Column(name="turno_preferido")private String preferredShift;private String mensaje;@Column(name="consentimiento_privacidad",nullable=false)private boolean privacyConsent;@Enumerated(EnumType.STRING)@Column(nullable=false)private BookingRequestStatus estado;@Column(name="observacion_interna")private String internalObservation;@Column(name="cita_id")private Long appointmentId;@Column(name="atendido_por")private Long attendedBy;@Column(name="creado_en",nullable=false)private Instant createdAt;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;@Version private Long version;protected PublicBookingRequest(){}public PublicBookingRequest(String name,String document,String mobile,String email,String service,LocalDate date,String shift,String message){fullName=name;documentNumber=document;celular=mobile;this.email=email;servicio=service;preferredDate=date;preferredShift=shift;mensaje=message;privacyConsent=true;estado=BookingRequestStatus.PENDIENTE;}public void change(BookingRequestStatus status,String observation,Long appointment,Long actor){estado=status;internalObservation=observation;appointmentId=appointment;attendedBy=actor;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public String getFullName(){return fullName;}public String getDocumentNumber(){return documentNumber;}public String getMobile(){return celular;}public String getEmail(){return email;}public String getService(){return servicio;}public LocalDate getPreferredDate(){return preferredDate;}public String getPreferredShift(){return preferredShift;}public String getMessage(){return mensaje;}public BookingRequestStatus getStatus(){return estado;}public String getInternalObservation(){return internalObservation;}public Long getAppointmentId(){return appointmentId;}public Long getAttendedBy(){return attendedBy;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Long getVersion(){return version;}}
